BASE06_agentic_grep_0a33bf39.final_sparql:
PREFIX tro: <http://example.org/ontology/transport#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?line ?lineTitle ?totalStopEvents ?avgStopEventsPerJourney
WHERE {
  # Get all lines with their full titles
  ?line a tro:Line .
  ?line tro:fullTitle ?lineTitle .

  # Count total stop events for each line
  {
    SELECT ?line (COUNT(?stopEvent) AS ?totalStopEvents)
    WHERE {
      ?stopEvent a tro:StopEvent .
      ?stopEvent tro:journey ?trip .
      ?trip tro:line ?line .
    }
    GROUP BY ?line
  }

  # Count journeys (trips) for each line
  {
    SELECT ?line (COUNT(DISTINCT ?trip) AS ?journeyCount)
    WHERE {
      ?trip a tro:Trip .
      ?trip tro:line ?line .
    }
    GROUP BY ?line
  }

  # Calculate average stop events per journey
  BIND((?totalStopEvents / ?journeyCount) AS ?avgStopEventsPerJourney)
}
ORDER BY ?lineTitle

